const $=id=>document.getElementById(id);let t=1,step=0,playing=false,last=null,raf;const fmt=n=>Number(n.toFixed(2)).toString();
function geometry(x){const px=x<=2?0:x<=6?2*x-4:8,py=x<=2?2*x:x<=6?4:16-2*x,qx=Math.min(2*x,8);return {px,py,qx,area:qx*py/2}}
function lesson(){const pages=[`<div class="eyebrow">① 0 ≦ x ≦ 2</div><h2>PはAB上、QはAD上</h2><p>２点とも毎秒2 cmだから、底辺AQ＝2x cm、高さAP＝2x cmだ。PがBに着くのは4÷2＝2秒後。</p><div class="formula">y＝2x × 2x ÷ 2＝2x²</div><p>底辺も高さも伸びるから、グラフは曲線になるぞ。</p>`,`<div class="eyebrow">② 2 ≦ x ≦ 4</div><h2>PはBC上、Qはまだ動く</h2><p>底辺AQ＝2x cm。PがBC上にいるので、高さは4 cmで一定だ。QがDに着くのは8÷2＝4秒後。</p><div class="formula">y＝2x × 4 ÷ 2＝4x</div><p>１秒ごとに面積が4 cm²ずつ増えるから、グラフは直線だぞ。</p>`,`<div class="eyebrow">③ 4 ≦ x ≦ 6</div><h2>QはDで停止、PはBC上</h2><p>底辺AQ＝AD＝8 cm。高さも4 cmのまま。Pが横に動いても、面積は変わらないんだ！ PがCに着くのは(4＋8)÷2＝6秒後。</p><div class="formula">y＝8 × 4 ÷ 2＝16</div><p>グラフは横向きの直線になるぞ。</p>`,`<div class="eyebrow">④ 6 ≦ x ≦ 8</div><h2>PがCDを下り、QはDで待つ</h2><p>底辺AQ＝8 cm。PがDに着くまでの道のりが高さPDになる。全行程は4＋8＋4＝16 cmだから、高さPD＝16−2x cmだ。</p><div class="formula">y＝8 × (16−2x) ÷ 2<br>　＝−8x＋64</div><p>Pは16÷2＝8秒でDへ。面積は１秒に8 cm²ずつ減り、最後は0になるぞ。</p>`,`<div class="eyebrow">⑤ 長方形の面積の４分の１</div><h2>面積が8 cm²になる時刻を探そう</h2><p>長方形の面積は4×8＝32 cm²。求める面積は32÷4＝<strong>8 cm²</strong>だ。</p><p>① 2x²＝8 → x²＝4 → 範囲内は<strong>x＝2</strong>。<br>② 4x＝8 → <strong>x＝2</strong>（①と同じ時刻）。<br>③ 面積は16なので該当なし。<br>④ −8x＋64＝8 → <strong>x＝7</strong>。</p><div class="formula">答え：2秒後、7秒後</div><form id="quiz"><label for="answer">5秒後の面積は？ </label><input id="answer" type="number" step="any" required aria-label="5秒後の面積"> cm² <button class="primary" type="submit">確かめる</button></form><p id="feedback" aria-live="polite"></p>`];$('lesson').innerHTML=pages[step];if(step===4)$('quiz').onsubmit=e=>{e.preventDefault();const ok=Number($('answer').value)===16;$('feedback').textContent=ok?'正解だ！ Qが止まり、底辺8 cm・高さ4 cmで16 cm²だぞ。':'5秒は③の区間。底辺と高さがそれぞれ何cmか確認しよう。';if(ok)setTime(5)}}
function render(){const g=geometry(t),px=130+60*g.px,py=305-60*g.py,qx=130+60*g.qx;const put=(id,a)=>Object.entries(a).forEach(([k,v])=>$(id).setAttribute(k,v));put('triangle',{points:`130,305 ${px},${py} ${qx},305`});put('base',{d:`M130 305H${qx}`});put('height',{d:`M${px} ${py}V305`});put('rightAngle',{d:t>0&&t<8?`M${px} 293h${t<=2?12:-12}v12`:''});put('pDot',{cx:px,cy:py});put('qDot',{cx:qx,cy:305});put('pLabel',{x:t<=2?px-29:t<=6?px-7:px+15,y:t<=2?py+6:t<=6?py-15:py+6});put('qLabel',{x:qx-8,y:332});$('pLabel').textContent=t===0||t===8?'':t===2?'P・B':t===6?'P・C':'P';$('qLabel').textContent=t===0?'':t===8?'P・Q・D':t>=4?'Q・D':'Q';$('aLabel').textContent=t===0?'A・P・Q':'A';$('bLabel').style.display=t===2?'none':'';$('cLabel').style.display=t===6?'none':'';$('dLabel').style.display=t>=4?'none':'';put('heightLabel',{x:px+16,y:(py+305)/2});$('heightLabel').textContent=t>0&&t<8?`高さ ${fmt(g.py)} cm`:'';put('baseLabel',{x:(130+qx)/2,y:367});$('baseLabel').textContent=`AQ ${fmt(g.qx)} cm`;$('time').textContent=t.toFixed(1);$('slider').value=t;$('baseValue').textContent=fmt(g.qx);$('heightValue').textContent=fmt(g.py);$('areaValue').textContent=fmt(g.area);const i=t<2?0:t<4?1:t<6?2:3;$('location').textContent=['① PはAB上・QはAD上','② PはBC上・QはAD上','③ PはBC上・QはDで停止','④ PはCD上・QはDで停止'][i];$('liveFormula').textContent=['y＝2x² （0 ≦ x ≦ 2）','y＝4x （2 ≦ x ≦ 4）','y＝16 （4 ≦ x ≦ 6）','y＝−8x＋64 （6 ≦ x ≦ 8）'][i];const gx=45+42.5*t,gy=205-11.25*g.area;put('dot',{cx:gx,cy:gy});put('guide',{d:`M45 ${gy}H${gx}V205`})}
function stop(){playing=false;cancelAnimationFrame(raf);$('play').textContent='▶ 再生'}function setTime(n){stop();t=n;render()}function frame(now){if(!playing)return;if(last!==null)t=Math.min(8,t+(now-last)/1000);last=now;render();if(t>=8)stop();else raf=requestAnimationFrame(frame)}$('slider').oninput=e=>setTime(Number(e.target.value));$('reset').onclick=()=>setTime(0);document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>setTime(Number(b.dataset.time)));$('play').onclick=()=>{if(playing)return stop();if(t>=8)t=0;playing=true;last=null;$('play').textContent='Ⅱ 一時停止';raf=requestAnimationFrame(frame)};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);document.querySelectorAll('[data-step]').forEach(btn=>{const on=Number(btn.dataset.step)===step;btn.classList.toggle('active',on);btn.setAttribute('aria-pressed',on)});lesson();if(step<4)setTime(1+step*2)});window.addEventListener('pagehide',stop);lesson();render();
